import { CommonModule, DatePipe, NgFor } from '@angular/common';
import { Component, OnInit, inject } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { Movement, MovementService } from '../../core/services/movement.service';
import { NotificationService } from '../../core/services/notification.service';
import { ResourceItem, ResourceService } from '../../core/services/resource.service';
import { Tire, TireService } from '../../core/services/tire.service';

@Component({
  selector: 'app-movements',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, NgFor, DatePipe],
  template: `
    <section class="page-header">
      <div>
        <span class="eyebrow">Movimientos</span>
        <h2>Traslado de gomas entre deposito, semis y tractores</h2>
        <p class="section-copy">Registra cada cambio de ubicacion con trazabilidad completa de responsable, fecha y observaciones.</p>
      </div>
    </section>

    <section class="panel-grid two-columns">
      <article class="panel-card">
        <div class="panel-head">
          <h3>Registrar movimiento</h3>
          <span class="chip">{{ movements.length }} movimientos</span>
        </div>
        <form class="form-grid" [formGroup]="form" (ngSubmit)="saveMovement()">
          <label class="field-label full-span">
            <span>Buscar goma</span>
            <input type="text" [value]="tireSearch" (input)="tireSearch = getInputValue($event)" placeholder="Escribe codigo, marca o ubicacion" />
          </label>
          <label class="field-label">
            <span>Goma a mover</span>
            <select formControlName="tireId">
              <option value="">Seleccionar goma</option>
              <option *ngFor="let tire of filteredTires()" [value]="tire.id">{{ tire.code }} | {{ tire.locationDetail.label }}</option>
            </select>
          </label>
          <label class="field-label">
            <span>Nuevo destino</span>
            <select formControlName="newLocation">
              <option value="DEPOSIT">Mover a deposito</option>
              <option value="SEMI">Mover a semi</option>
              <option value="TRACTOR">Mover a tractor</option>
            </select>
          </label>
          <label class="field-label full-span" *ngIf="form.value.newLocation === 'DEPOSIT'">
            <span>Buscar deposito</span>
            <input type="text" [value]="depositSearch" (input)="depositSearch = getInputValue($event)" placeholder="Escribe nombre del deposito" />
          </label>
          <label class="field-label" *ngIf="form.value.newLocation === 'DEPOSIT'">
            <span>Deposito destino</span>
            <select formControlName="depositId">
              <option value="">Seleccionar deposito</option>
              <option *ngFor="let deposit of filteredDeposits()" [value]="deposit.id">{{ deposit.name }}</option>
            </select>
          </label>
          <label class="field-label full-span" *ngIf="form.value.newLocation === 'SEMI'">
            <span>Buscar semi</span>
            <input type="text" [value]="semiSearch" (input)="semiSearch = getInputValue($event)" placeholder="Escribe patente, marca o modelo" />
          </label>
          <label class="field-label" *ngIf="form.value.newLocation === 'SEMI'">
            <span>Semi destino</span>
            <select formControlName="semiId">
              <option value="">Seleccionar semi</option>
              <option *ngFor="let semi of filteredSemis()" [value]="semi.id">{{ semi.plate }}</option>
            </select>
          </label>
          <label class="field-label full-span" *ngIf="form.value.newLocation === 'TRACTOR'">
            <span>Buscar tractor</span>
            <input type="text" [value]="tractorSearch" (input)="tractorSearch = getInputValue($event)" placeholder="Escribe patente, marca o modelo" />
          </label>
          <label class="field-label" *ngIf="form.value.newLocation === 'TRACTOR'">
            <span>Tractor destino</span>
            <select formControlName="tractorId">
              <option value="">Seleccionar tractor</option>
              <option *ngFor="let tractor of filteredTractors()" [value]="tractor.id">{{ tractor.plate }}</option>
            </select>
          </label>
          <label class="field-label full-span">
            <span>Observacion del traslado</span>
            <textarea rows="3" placeholder="Motivo del movimiento o comentario tecnico" formControlName="notes"></textarea>
          </label>
          <div class="form-actions">
            <button class="primary-button" type="submit">Guardar movimiento</button>
          </div>
        </form>
      </article>

      <article class="panel-card">
        <div class="panel-head">
          <h3>Historial global</h3>
        </div>
        <div class="timeline">
          <div class="timeline-item" *ngFor="let movement of movements">
            <div>
              <strong>{{ movement.tire.code }}</strong>
              <p>{{ movement.previousLocation }} -> {{ movement.newLocation }} {{ movement.newPlate ? '(' + movement.newPlate + ')' : '' }}</p>
              <p>{{ movement.notes || 'Sin observaciones' }}</p>
            </div>
            <small>{{ movement.user.name }} | {{ movement.createdAt | date:'short' }}</small>
          </div>
        </div>
      </article>
    </section>
  `,
})
export class MovementsComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly movementService = inject(MovementService);
  private readonly tireService = inject(TireService);
  private readonly resourceService = inject(ResourceService);
  private readonly notificationService = inject(NotificationService);

  tires: Tire[] = [];
  movements: Movement[] = [];
  deposits: ResourceItem[] = [];
  tractors: ResourceItem[] = [];
  semis: ResourceItem[] = [];

  tireSearch = '';
  depositSearch = '';
  tractorSearch = '';
  semiSearch = '';

  readonly form = this.fb.nonNullable.group({
    tireId: ['', Validators.required],
    newLocation: ['DEPOSIT', Validators.required],
    depositId: [''],
    semiId: [''],
    tractorId: [''],
    notes: [''],
  });

  ngOnInit(): void {
    this.loadData();
  }

  getInputValue(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  private includesText(...values: Array<string | null | undefined>): boolean {
    const searchTerms = [this.tireSearch, this.depositSearch, this.tractorSearch, this.semiSearch];
    return searchTerms.some((term) => term.length > 0) ? true : true;
  }

  private normalize(value: string): string {
    return value.trim().toLowerCase();
  }

  filteredTires(): Tire[] {
    const query = this.normalize(this.tireSearch);
    if (!query) return this.tires;
    return this.tires.filter((tire) =>
      [tire.code, tire.brand, tire.model, tire.size, tire.locationDetail.label].some((value) => this.normalize(value).includes(query)),
    );
  }

  filteredDeposits(): ResourceItem[] {
    const query = this.normalize(this.depositSearch);
    if (!query) return this.deposits;
    return this.deposits.filter((deposit) => this.normalize(deposit.name || '').includes(query));
  }

  filteredTractors(): ResourceItem[] {
    const query = this.normalize(this.tractorSearch);
    if (!query) return this.tractors;
    return this.tractors.filter((tractor) =>
      [tractor.plate || '', tractor.brand || '', tractor.model || ''].some((value) => this.normalize(value).includes(query)),
    );
  }

  filteredSemis(): ResourceItem[] {
    const query = this.normalize(this.semiSearch);
    if (!query) return this.semis;
    return this.semis.filter((semi) =>
      [semi.plate || '', semi.brand || '', semi.model || ''].some((value) => this.normalize(value).includes(query)),
    );
  }

  loadData(): void {
    this.tireService.getAll({}).subscribe((items) => (this.tires = items));
    this.movementService.getAll().subscribe((items) => (this.movements = items));
    this.resourceService.getDeposits().subscribe((items) => (this.deposits = items));
    this.resourceService.getTractors().subscribe((items) => (this.tractors = items));
    this.resourceService.getSemis().subscribe((items) => (this.semis = items));
  }

  saveMovement(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.movementService.create(this.form.getRawValue()).subscribe({
      next: () => {
        this.notificationService.show('success', 'Movimiento registrado correctamente.');
        this.form.patchValue({ tireId: '', notes: '', depositId: '', semiId: '', tractorId: '' });
        this.loadData();
      },
      error: (error) => {
        this.notificationService.show('error', error.error?.message || 'No se pudo registrar el movimiento.');
      },
    });
  }
}
